"""홀핀글로벌 로고 (투명 PNG를 gzip+base64로 보관). HTML의 /_blob/<id> 와 {{logo:dark|white|mono}} 를 data URI로 바꿉니다."""
import base64
import gzip

LOGOS_GZ = {
    "6f5c8e139d4307a4682d90c184946150": ("dark", ""),
    "7283b6de69e1b39b619f1e291f120006": ("white", ""),
    "c8a9aedf73d0370660075c6968744e43": ("mono", ""),
}

LOGOS = {k: (name, base64.b64encode(gzip.decompress(base64.b64decode(gz))).decode())
         for k, (name, gz) in LOGOS_GZ.items()}


def fix(html):
    for blob, (name, b64) in LOGOS.items():
        uri = "data:image/png;base64," + b64
        html = html.replace("/_blob/" + blob, uri).replace("{{logo:" + name + "}}", uri)
    return html
